STORE_HEADER_OTHER="x-store-id: test-store-002"

# ============================================
# Helper Functions
# ============================================

# Extract a top-level field from a JSON response.
# NEVER use grep for ID extraction — nested objects may serialize before the root ID.
extract_field() {
    local json=$1
    local field=$2
    if command -v jq &>/dev/null; then
        echo "$json" | jq -r ".$field"
    else
        echo "$json" | python3 -c "import sys,json; d=json.load(sys.stdin); print(d.get('$field',''))"
    fi
}

# Capture BOTH status code AND response body in a single request.
# Sets globals: LAST_STATUS and LAST_BODY. Optional 4th arg overrides the store header.
capture_with_status() {
    local http_method=$1
    local url=$2
    local payload=$3
    local store_hdr=${4:-$STORE_HEADER}
    local response

    if [ -n "$payload" ] && [ "$payload" != "null" ]; then
        response=$(curl -s -w "\n%{http_code}" -X "$http_method" "$url" \
            -H 'Content-Type: application/json' -H "$TENANT_HEADER" -H "$store_hdr" -d "$payload")
    else
        response=$(curl -s -w "\n%{http_code}" -X "$http_method" "$url" \
            -H "$TENANT_HEADER" -H "$store_hdr")
    fi

    LAST_STATUS=$(echo "$response" | tail -1)
    LAST_BODY=$(echo "$response" | sed '$d')
}

# Assert exact HTTP status (contract fidelity). Optional 8th arg overrides the store header.
assert_status() {
    local test_num=$1
    local test_name=$2
    local rule_id=$3
    local http_method=$4
    local url=$5
    local payload=$6
    local expected_status=$7
    local store_hdr=${8:-$STORE_HEADER}

    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $test_name${NC}"
    echo -e "  Rule: $rule_id | Expected Status: $expected_status"

    capture_with_status "$http_method" "$url" "$payload" "$store_hdr"

    if [ "$LAST_STATUS" = "$expected_status" ]; then
        echo -e "  ${GREEN}PASSED${NC} (HTTP $LAST_STATUS)"
        PASSED=$((PASSED + 1))
        return 0
    else
        echo -e "  ${RED}FAILED${NC} (Expected: $expected_status, Got: $LAST_STATUS)"
        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Expected $expected_status, Got $LAST_STATUS")
        return 1
    fi
}

# Assert exact HTTP status AND capture body for follow-on extraction (single request).
