    "POST" "$BASE_URL/customer-options" \
    "{\"code\":\"OPTCASC_$SFX\",\"type\":\"Text\",\"active\":true,\"public\":true,\"descriptions\":[{\"language\":\"en\",\"name\":\"Casc\"}]}" \
    "201"
