assert_status_and_capture 78 "Create value for cascade test" "BR-CUSTOPT-013" \
    "POST" "$BASE_URL/customer-option-values" \
    "{\"code\":\"VALCASC_$SFX\",\"descriptions\":[{\"language\":\"en\",\"name\":\"CascVal\"}]}" \
    "201"
CASC_VAL_ID=$(extract_field "$LAST_BODY" "id")

assert_status 79 "Bind (option,value) for cascade test (201)" "BR-CUSTOPT-013" \
    "POST" "$BASE_URL/customer-option-sets" \
