    "PUT" "$BASE_URL/customers/$ATTR_CUST_ID/attributes" \
    "{\"attributes\":[{\"option_id\":\"$CASC_OPT_ID\",\"text_value\":\"casc\"}]}" \
    "200"

# Delete the option — the DB ON DELETE CASCADE removes dependent attributes & bindings.
assert_status 81 "Delete the customer option (204)" "BR-CUSTOPT-013" \
    "DELETE" "$BASE_URL/customer-options/$CASC_OPT_ID" "null" "204"

# Assert the cascade EFFECT: the shopper's attribute for that option is gone.
assert_json_absent 82 "Cascade effect: shopper attribute for deleted option is gone" "BR-CUSTOPT-013" \
    "GET" "$BASE_URL/customers/$ATTR_CUST_ID/attributes" "null" "\"text_value\":\"casc\"" 

assert_status 83 "Deleted option is gone (GET -> 404)" "BR-CUSTOPT-013" \
    "GET" "$BASE_URL/customer-options/$CASC_OPT_ID" "null" "404"

